@keyframes pulse {
  0%,
  100% {
    opacity: 1;
  }
  50% {
    opacity: 0.5;
  }
}

/* ---------------------------------------------------------------------------
 * View transitions
 * Class names below match the `share` / `enter` / `exit` props passed to
 * React's <ViewTransition> in the page components.
 * ------------------------------------------------------------------------- */

:root {
  --duration-exit: 150ms;
  --duration-enter: 210ms;
  --duration-move: 400ms;
}

/* Let clicks reach the live page while a transition is running. */
::view-transition {
  pointer-events: none;
}

/* Shared element: product thumbnail <-> detail hero */
::view-transition-group(.morph) {
  animation-duration: var(--duration-move);
  z-index: 10;
}
::view-transition-image-pair(.morph) {
  animation-name: via-blur;
}
@keyframes via-blur {
  30% {
    filter: blur(3px);
  }
}

/* Suspense reveal: skeleton yields downward, content arrives from below.
 * The enter fade is delayed until the exit finishes so they don't overlap. */
::view-transition-old(.slide-down) {
  animation:
    var(--duration-exit) ease-out both fade reverse,
    var(--duration-exit) ease-out both slide-y reverse;
}
::view-transition-new(.slide-up) {
  animation:
    var(--duration-enter) ease-in var(--duration-exit) both fade,
    var(--duration-move) ease-in both slide-y;
}

/* Directional navigation: forward slides content left, back slides it right. */
::view-transition-old(.nav-forward) {
  --slide-offset: -60px;
  animation:
    var(--duration-exit) ease-in both fade reverse,
    var(--duration-move) ease-in-out both slide-x reverse;
}
::view-transition-new(.nav-forward) {
  --slide-offset: 60px;
  animation:
    var(--duration-enter) ease-out var(--duration-exit) both fade,
    var(--duration-move) ease-in-out both slide-x;
}
::view-transition-old(.nav-back) {
  --slide-offset: 60px;
  animation:
    var(--duration-exit) ease-in both fade reverse,
    var(--duration-move) ease-in-out both slide-x reverse;
}
::view-transition-new(.nav-back) {
  --slide-offset: -60px;
  animation:
    var(--duration-enter) ease-out var(--duration-exit) both fade,
    var(--duration-move) ease-in-out both slide-x;
}

@keyframes fade {
  from {
    filter: blur(3px);
    opacity: 0;
  }
  to {
    filter: blur(0);
    opacity: 1;
  }
}
@keyframes slide-y {
  from {
    transform: translateY(10px);
  }
  to {
    transform: translateY(0);
  }
}
@keyframes slide-x {
  from {
    translate: var(--slide-offset);
  }
  to {
    translate: 0;
  }
}

/* Reduced motion: drop every positional animation (morph travel, slides) and
 * blur, keeping only short opacity fades so state changes are still legible.
 * The skeleton pulse becomes static. */
@media (prefers-reduced-motion: reduce) {
  ::view-transition-group(.morph),
  ::view-transition-image-pair(.morph) {
    animation: none;
  }

  ::view-transition-old(.slide-down),
  ::view-transition-old(.nav-forward),
  ::view-transition-old(.nav-back) {
    animation: var(--duration-exit) ease-out both fade-only reverse;
  }
  ::view-transition-new(.slide-up),
  ::view-transition-new(.nav-forward),
  ::view-transition-new(.nav-back) {
    animation: var(--duration-enter) ease-in var(--duration-exit) both fade-only;
  }

  .skeleton-image,
  .skeleton-text {
    animation: none;
  }
}

@keyframes fade-only {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}

